from pathlib import Path


def replace(path, old, new, label):
    p = Path(path)
    text = p.read_text(encoding='utf-8')
    if old not in text:
        raise SystemExit(f'Missing anchor for {label} in {path}')
    p.write_text(text.replace(old, new, 1), encoding='utf-8')
    print('patched', label)

